#!/usr/bin/env node
/**
 * NervePay Auto-Instrumentation
 *
 * Automatically intercepts ALL HTTP/HTTPS requests and tracks them to NervePay.
 * NO CODE CHANGES NEEDED - agents don't need to remember to track.
 *
 * SETUP:
 *   1. Set required env vars (NERVEPAY_DID, NERVEPAY_PRIVATE_KEY)
 *   2. Load this script before running your agent:
 *      node --import ./nervepay-skill/nervepay-instrument.mjs your-agent.js
 *
 *   OR set in environment:
 *      export NODE_OPTIONS="--import /path/to/nervepay-instrument.mjs"
 *
 * HOW IT WORKS:
 *   - Patches global fetch() to intercept all HTTP calls
 *   - Also patches http.request() and https.request()
 *   - Automatically tracks each call to NervePay (async, non-blocking)
 *   - Filters out calls to NervePay itself (don't track tracking!)
 *   - Captures timing, success/failure, and response codes
 */

import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
import { spawn } from 'node:child_process';
import * as http from 'node:http';
import * as https from 'node:https';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

// Configuration
const NERVEPAY_API_URL = process.env.NERVEPAY_API_URL || 'https://api.nervepay.xyz';
const NERVEPAY_DID = process.env.NERVEPAY_DID;
const NERVEPAY_PRIVATE_KEY = process.env.NERVEPAY_PRIVATE_KEY;
const NERVEPAY_AUTO_TRACK = process.env.NERVEPAY_AUTO_TRACK !== 'false'; // Opt-out via env var

// Don't track if credentials are missing
const canTrack = NERVEPAY_DID && NERVEPAY_PRIVATE_KEY && NERVEPAY_AUTO_TRACK;

if (!canTrack) {
  if (!NERVEPAY_AUTO_TRACK) {
    console.warn('[NervePay] Auto-tracking disabled via NERVEPAY_AUTO_TRACK=false');
  } else if (!NERVEPAY_DID || !NERVEPAY_PRIVATE_KEY) {
    console.warn('[NervePay] Auto-tracking disabled: Missing NERVEPAY_DID or NERVEPAY_PRIVATE_KEY');
  }
}

// Helper: Extract service name and endpoint from URL
function parseUrl(url) {
  try {
    const parsed = typeof url === 'string' ? new URL(url) : url;
    const serviceName = parsed.hostname.replace(/^(www\.|api\.)/, '').split('.')[0];
    const endpoint = parsed.pathname;
    return { serviceName, endpoint, hostname: parsed.hostname };
  } catch {
    return { serviceName: 'unknown', endpoint: '/', hostname: 'unknown' };
  }
}

// Helper: Should we track this URL?
function shouldTrack(url) {
  if (!canTrack) return false;

  try {
    const parsed = typeof url === 'string' ? new URL(url) : url;
    const hostname = parsed.hostname;

    // Don't track calls to NervePay API itself (avoid infinite loop)
    if (hostname.includes('nervepay.xyz') || hostname.includes('nervepay')) {
      return false;
    }

    // Don't track localhost/internal calls
    if (hostname === 'localhost' || hostname === '127.0.0.1' || hostname.startsWith('192.168.') || hostname.startsWith('10.')) {
      return false;
    }

    return true;
  } catch {
    return false;
  }
}

// Helper: Track to NervePay (async, non-blocking)
function trackToNervePay(serviceName, endpoint, method, success, responseTimeMs, statusCode) {
  if (!shouldTrack(`https://${serviceName}`)) return;

  const trackScript = join(__dirname, 'nervepay-track.mjs');

  // Build command args
  const args = [
    trackScript,
    serviceName,
    endpoint,
    success ? 'success' : 'failure',
    responseTimeMs.toString(),
  ];

  if (method) args.push('', method); // Empty amount, then method

  // Spawn as detached background process (don't block)
  const child = spawn('node', args, {
    detached: true,
    stdio: 'ignore',
    env: process.env
  });

  child.unref(); // Let parent exit without waiting
}

// ============================================================================
// PATCH GLOBAL FETCH
// ============================================================================

if (typeof globalThis.fetch === 'function') {
  const originalFetch = globalThis.fetch;

  globalThis.fetch = async function patchedFetch(url, options = {}) {
    if (!shouldTrack(url)) {
      return originalFetch(url, options);
    }

    const { serviceName, endpoint } = parseUrl(url);
    const method = (options.method || 'GET').toUpperCase();
    const startTime = Date.now();

    try {
      const response = await originalFetch(url, options);
      const responseTime = Date.now() - startTime;
      const success = response.ok;

      // Track in background
      trackToNervePay(serviceName, endpoint, method, success, responseTime, response.status);

      return response;
    } catch (error) {
      const responseTime = Date.now() - startTime;

      // Track failure
      trackToNervePay(serviceName, endpoint, method, false, responseTime, 0);

      throw error;
    }
  };

  console.log('[NervePay] Instrumented: global fetch()');
}

// ============================================================================
// PATCH HTTP.REQUEST AND HTTPS.REQUEST
// ============================================================================

function patchHttpModule(httpModule, moduleName) {
  const originalRequest = httpModule.request;

  // Use Object.defineProperty to override read-only property
  try {
    Object.defineProperty(httpModule, 'request', {
      value: function patchedRequest(...args) {
    // Parse URL from arguments (can be url string, URL object, or options object)
    let url = args[0];
    if (typeof url === 'string') {
      url = `${moduleName}://${url}`;
    } else if (url instanceof URL) {
      url = url.href;
    } else if (typeof url === 'object') {
      const protocol = moduleName === 'https' ? 'https:' : 'http:';
      const hostname = url.hostname || url.host || 'localhost';
      const port = url.port ? `:${url.port}` : '';
      const path = url.path || '/';
      url = `${protocol}//${hostname}${port}${path}`;
    }

    if (!shouldTrack(url)) {
      return originalRequest.apply(this, args);
    }

    const { serviceName, endpoint } = parseUrl(url);
    const startTime = Date.now();
    let tracked = false;

    const request = originalRequest.apply(this, args);

    // Track on response
    request.on('response', (response) => {
      if (tracked) return;
      tracked = true;

      const responseTime = Date.now() - startTime;
      const success = response.statusCode >= 200 && response.statusCode < 400;
      const method = request.method || 'GET';

      trackToNervePay(serviceName, endpoint, method, success, responseTime, response.statusCode);
    });

    // Track on error
    request.on('error', () => {
      if (tracked) return;
      tracked = true;

      const responseTime = Date.now() - startTime;
      const method = request.method || 'GET';

      trackToNervePay(serviceName, endpoint, method, false, responseTime, 0);
    });

    return request;
      },
      writable: true,
      configurable: true
    });

    console.log(`[NervePay] Instrumented: ${moduleName}.request()`);
  } catch (error) {
    console.warn(`[NervePay] Could not instrument ${moduleName}.request():`, error.message);
  }
}

patchHttpModule(http, 'http');
patchHttpModule(https, 'https');

console.log('[NervePay] Auto-instrumentation active. All external HTTP calls will be tracked automatically.');
console.log('[NervePay] To disable: export NERVEPAY_AUTO_TRACK=false');

#!/usr/bin/env node
/**
 * NervePay Request Helper
 *
 * Zero-dependency Ed25519 signing helper for agents.
 * Uses only Node.js built-in crypto.
 *
 * USAGE:
 *   export NERVEPAY_DID="did:nervepay:agent:abc123..."
 *   export NERVEPAY_PRIVATE_KEY="ed25519:5Kd7..."
 *   export NERVEPAY_API_URL="https://api.nervepay.xyz"  # optional
 *
 *   # Authenticated GET
 *   node nervepay-request.mjs GET /v1/agent-identity/whoami
 *
 *   # Authenticated POST with body
 *   node nervepay-request.mjs POST /v1/agent-identity/track-service '{"service_name":"openai"}'
 */

import crypto from 'node:crypto';

// ============================================================================
// CONFIGURATION
// ============================================================================

const API_URL = process.env.NERVEPAY_API_URL || 'https://api.nervepay.xyz';
const AGENT_DID = process.env.NERVEPAY_DID;
const AGENT_PRIVATE_KEY = process.env.NERVEPAY_PRIVATE_KEY;

// ============================================================================
// BASE58 ENCODING
// ============================================================================

const BASE58_ALPHABET = '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';

function decodeBase58(str) {
  const bytes = [];
  for (const char of str) {
    const index = BASE58_ALPHABET.indexOf(char);
    if (index === -1) throw new Error(`Invalid base58 character: ${char}`);

    let carry = index;
    for (let i = 0; i < bytes.length; i++) {
      carry += bytes[i] * 58;
      bytes[i] = carry & 0xff;
      carry >>= 8;
    }
    while (carry > 0) {
      bytes.push(carry & 0xff);
      carry >>= 8;
    }
  }

  for (const char of str) {
    if (char !== '1') break;
    bytes.push(0);
  }

  return Buffer.from(bytes.reverse());
}

// ============================================================================
// ED25519 SIGNING
// ============================================================================

function signRequest(privateKeyBase58, payload) {
  const keyStr = privateKeyBase58.replace(/^ed25519:/, '');
  const privateKeyBytes = decodeBase58(keyStr);
  const seed = Uint8Array.prototype.slice.call(privateKeyBytes, 0, 32);

  const pkcs8Header = Buffer.from('302e020100300506032b657004220420', 'hex');
  const keyObject = crypto.createPrivateKey({
    key: Buffer.concat([pkcs8Header, seed]),
    format: 'der',
    type: 'pkcs8'
  });

  const message = JSON.stringify(payload);
  const signature = crypto.sign(null, Buffer.from(message), keyObject);

  return signature.toString('base64');
}

// ============================================================================
// REQUEST BUILDER
// ============================================================================

function generateAuthHeaders(did, privateKey, method, path, query = null, body = null) {
  const nonce = crypto.randomUUID();
  const timestamp = new Date().toISOString();

  // Hash body if present (must match backend's SHA-256 hashing)
  let bodyHash = null;
  if (body) {
    const hash = crypto.createHash('sha256').update(body).digest('hex');
    bodyHash = hash;
  }

  const payload = {
    method: method.toUpperCase(),
    path,
    query,
    body: bodyHash,
    nonce,
    timestamp,
    agent_did: did,
  };

  const signature = signRequest(privateKey, payload);

  return {
    'Agent-DID': did,
    'X-Agent-Signature': signature,
    'X-Agent-Nonce': nonce,
    'X-Signature-Timestamp': timestamp,
  };
}

async function makeRequest(method, path, bodyStr = null) {
  if (!AGENT_DID || !AGENT_PRIVATE_KEY) {
    console.error(JSON.stringify({
      error: 'Missing required environment variables',
      required: ['NERVEPAY_DID', 'NERVEPAY_PRIVATE_KEY']
    }, null, 2));
    process.exit(1);
  }

  // Parse query string from path
  const [pathOnly, queryStr] = path.split('?');
  const query = queryStr || null;

  const url = query ? `${API_URL}${pathOnly}?${query}` : `${API_URL}${pathOnly}`;
  const headers = generateAuthHeaders(AGENT_DID, AGENT_PRIVATE_KEY, method, pathOnly, query, bodyStr);

  if (bodyStr) {
    headers['Content-Type'] = 'application/json';
  }

  try {
    const response = await fetch(url, {
      method,
      headers,
      body: bodyStr || undefined,
    });

    const responseText = await response.text();

    let data;
    try {
      data = JSON.parse(responseText);
    } catch {
      data = responseText;
    }

    const result = {
      ok: response.ok,
      status: response.status,
      statusText: response.statusText,
      data,
    };

    console.log(JSON.stringify(result, null, 2));

    if (!response.ok) {
      process.exit(1);
    }
  } catch (error) {
    console.error(JSON.stringify({
      error: error.message,
      stack: error.stack
    }, null, 2));
    process.exit(1);
  }
}

// ============================================================================
// CLI
// ============================================================================

const [method, path, bodyStr] = process.argv.slice(2);

if (!method || !path) {
  console.error('Usage: nervepay-request.mjs METHOD PATH [BODY_JSON]');
  console.error('Example: nervepay-request.mjs GET /v1/agent-identity/whoami');
  console.error('Example: nervepay-request.mjs POST /v1/agent-identity/track-service \'{"service_name":"openai"}\'');
  process.exit(1);
}

makeRequest(method.toUpperCase(), path, bodyStr);

#!/usr/bin/env node
/**
 * NervePay Quick Track Helper
 *
 * Simplified wrapper for tracking external API calls.
 * Use this immediately after EVERY external API call.
 *
 * USAGE:
 *   # Minimal (required fields only)
 *   node nervepay-track.mjs openai /v1/chat/completions success
 *   node nervepay-track.mjs stripe /v1/charges failure
 *
 *   # With response time
 *   node nervepay-track.mjs openai /v1/chat/completions success 1250
 *
 *   # With cost
 *   node nervepay-track.mjs openai /v1/chat/completions success 1250 0.05
 *
 *   # Full details
 *   node nervepay-track.mjs openai /v1/chat/completions success 1250 0.05 POST USD
 */

import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
import { spawn } from 'node:child_process';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

// Parse arguments
const [serviceName, endpoint, successStr, responseTimeStr, amountStr, method, currency] = process.argv.slice(2);

if (!serviceName || !endpoint || !successStr) {
  console.error('Usage: nervepay-track.mjs SERVICE ENDPOINT success|failure [RESPONSE_TIME_MS] [AMOUNT] [METHOD] [CURRENCY]');
  console.error('');
  console.error('Examples:');
  console.error('  nervepay-track.mjs openai /v1/chat/completions success');
  console.error('  nervepay-track.mjs openai /v1/chat/completions success 1250');
  console.error('  nervepay-track.mjs openai /v1/chat/completions success 1250 0.05');
  console.error('  nervepay-track.mjs stripe /v1/charges failure 850 10.00 POST USD');
  process.exit(1);
}

const success = successStr.toLowerCase() === 'success';

// Build tracking payload
const payload = {
  service_name: serviceName,
  endpoint: endpoint,
  success: success,
};

if (method) payload.method = method;
if (responseTimeStr) payload.response_time_ms = parseInt(responseTimeStr, 10);
if (amountStr) payload.amount = amountStr;
if (currency) payload.currency = currency;

// Call the main nervepay-request.mjs script
const requestScript = join(__dirname, 'nervepay-request.mjs');
const body = JSON.stringify(payload);

const child = spawn('node', [requestScript, 'POST', '/v1/agent-identity/track-service', body], {
  stdio: 'inherit',
  env: process.env
});

child.on('exit', (code) => {
  process.exit(code || 0);
});
